import{_ as t,a as r,b as i}from"./chunks/bubbles-03.CRJ58gUA.js";import{_ as e,o as n,c as o,a3 as s}from"./chunks/framework.D1iekJsc.js";const f=JSON.parse('{"title":"气泡与输入框","description":"MiniTavern 聊天气泡和输入框样式：跟随主题，或单独改背景、圆角、旁白/动作/说话颜色和模糊。","frontmatter":{"title":"气泡与输入框","description":"MiniTavern 聊天气泡和输入框样式：跟随主题，或单独改背景、圆角、旁白/动作/说话颜色和模糊。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"气泡与输入框 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 聊天气泡和输入框样式：跟随主题，或单独改背景、圆角、旁白/动作/说话颜色和模糊。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/manual/bubbles"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/manual/bubbles"}]]},"headers":[],"relativePath":"manual/bubbles.md","filePath":"manual/bubbles.md","lastUpdated":1791862671000}'),l={name:"manual/bubbles.md"};function g(c,a,p,h,u,d){return n(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="气泡与输入框" tabindex="-1">气泡与输入框 <a class="header-anchor" href="#气泡与输入框" aria-label="Permalink to &quot;气泡与输入框&quot;">​</a></h1><p>路径：底部 <strong>设置</strong> → <strong>聊天设置</strong> → <strong>气泡与输入框</strong>。</p><p>这里改的是全局聊天外观。主题和字号仍在 <strong>设置 → 主题和字体</strong>。</p><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+t+'" alt="设置首页"><figcaption>1 · 设置 → 聊天设置</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="聊天设置里的气泡与输入框"><figcaption>2 · 气泡与输入框</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="气泡颜色和圆角"><figcaption>3 · 关掉跟随主题后改样式</figcaption></figure></div><h2 id="气泡" tabindex="-1">气泡 <a class="header-anchor" href="#气泡" aria-label="Permalink to &quot;气泡&quot;">​</a></h2><p><strong>气泡</strong>和 <strong>输入框</strong> 各有一个 <strong>跟随主题</strong>。打开时用当前主题。关掉之后，下面的配置会盖过主题；没填的颜色仍用主题。</p><ol><li><strong>AI 气泡背景</strong>、<strong>用户气泡背景</strong>：点进去是色环调色板。预设色是圆形，选中会打勾。可以改不透明度和颜色值，颜色值也能复制。一行上写着「使用主题颜色」时，这一项仍跟主题。</li><li><strong>圆角</strong>：数值越大角越圆。拖动之后用这里的数值，不再跟着主题间距缩放。</li><li>文字可以分开上色： <ul><li><strong>旁白文字</strong>、<strong>旁白背景</strong>：普通正文和加粗</li><li><strong>动作</strong>：<code>*星号*</code> 括起来的字</li><li><strong>说话</strong>：引号里的字</li><li><strong>内心戏</strong></li></ul></li><li>角色卡如果不是用这套记号写的，那些字仍会显示，只是走旁白样式。完整 HTML 卡片用自己的颜色，不靠这几项。</li></ol><h2 id="输入框" tabindex="-1">输入框 <a class="header-anchor" href="#输入框" aria-label="Permalink to &quot;输入框&quot;">​</a></h2><p>关掉输入框自己的 <strong>跟随主题</strong> 之后，可以改背景、圆角、占位符颜色、文本颜色、按钮图标颜色，以及 <strong>模糊</strong>。</p><p>模糊打开后可以调色调和强度。不支持模糊的 Android（API 31 以下）没有这个开关。iOS 在关掉跟随后，模糊默认是开的。</p><h2 id="预览" tabindex="-1">预览 <a class="header-anchor" href="#预览" aria-label="Permalink to &quot;预览&quot;">​</a></h2><p>右上角 <strong>预览</strong> 打开示例页：背景是当前语言的女性示例卡，下面有一段示例对话和输入框。最后一条是 AI 消息，带继续、智能回复等按钮，但点了不会发送。输入框也不能发送。左侧按钮和右上角设置同样点不了。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./chat">聊天</a>：气泡菜单、会话里的聊天设置</li><li><a href="./settings">设置与其它</a>：主题和字体</li></ul>',15)])])}const _=e(l,[["render",g]]);export{f as __pageData,_ as default};
